from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

wb=load_workbook('/root/data/workbook.xlsx', data_only=False)
ws=wb['Data']

# Check rows 18-24, cols A-T
print('[Data rows 18-24 cols A-T]')
for r in range(18,25):
    vals=[ws.cell(r,c).value for c in range(1,21)]
    print('Row',r,vals)

# Determine used range bounds (rough) by scanning for any values
max_row=ws.max_row
max_col=ws.max_column
print('\nData max_row',max_row,'max_col',max_col)

# For rows 21-38, list non-empty cells from A to max_col but only show columns with values
print('\n[Non-empty cells in Data rows 21-38]')
for r in range(21,39):
    non=[]
    for c in range(1,max_col+1):
        v=ws.cell(r,c).value
        if v is None or (isinstance(v,str) and v.strip()==''):
            continue
        non.append((c,v))
    # show first 15 non-empty and last 10
    def fmt(p):
        c,v=p
        return f"{get_column_letter(c)}{r}={v!r}"
    if not non:
        print('Row',r,'(empty)')
    else:
        head=[fmt(p) for p in non[:15]]
        tail=[fmt(p) for p in non[-10:]]
        if len(non) > 25:
            print('Row',r,'non-empty count',len(non),'head:',', '.join(head),'... tail:',', '.join(tail))
        else:
            print('Row',r,'non-empty count',len(non),', '.join(head))

# Identify candidate year header row by scanning a broader set of rows around 18-25
import re

def is_year(v):
    if isinstance(v,int) and 1900<=v<=2100:
        return True
    if isinstance(v,str):
        s=v.strip()
        if re.fullmatch(r'\d{4}', s):
            y=int(s)
            return 1900<=y<=2100
    return False

print('\n[Search for year-like values in rows 1-60]')
for r in range(1,61):
    years=[]
    for c in range(1,max_col+1):
        v=ws.cell(r,c).value
        if is_year(v):
            years.append((c,v))
    if years:
        yrs=', '.join([f"{get_column_letter(c)}{r}={v}" for c,v in years[:20]])
        print('Row',r,'years count',len(years),'->',yrs)

# Print row that has most year-like values
best=(None,0)
for r in range(1,max_row+1):
    cnt=0
    for c in range(1,max_col+1):
        if is_year(ws.cell(r,c).value):
            cnt+=1
    if cnt>best[1]:
        best=(r,cnt)
print('\nBest year header row candidate:',best)
if best[0] is not None:
    r=best[0]
    # show all non-empty in that row
    non=[]
    for c in range(1,max_col+1):
        v=ws.cell(r,c).value
        if v is None or (isinstance(v,str) and v.strip()==''):
            continue
        non.append((c,v))
    for c,v in non:
        print(f"{get_column_letter(c)}{r}={v!r}")

wb.close()
